**Function**: isValidInfix

```c
// C program for the function called isValidInfix
// Contains target function implementation and dependency signatures

#include <stdio.h>   /// for printf() and scanf()
#include <string.h>  /// for strlen() and strcmp()

// Forward declarations for dependency functions
int isOprnd(char ch);
int isOperator(char ch);

// Target function implementation
int isValidInfix(const char *expr)
{
    int i;
    int operandCount = 0;
    int operatorCount = 0;
    int parenBalance = 0;

    if (expr == NULL || expr[0] == '\0')
    {
        return 0;  // empty or null expression is invalid
    }

    for (i = 0; expr[i] != '\0'; i++)
    {
        char ch = expr[i];

        if (isOprnd(ch))
        {
            operandCount++;
        }
        else if (isOperator(ch))
        {
            operatorCount++;
        }
        else if (ch == '(')
        {
            parenBalance++;
        }
        else if (ch == ')')
        {
            parenBalance--;
            if (parenBalance < 0)
            {
                return 0;  // unmatched closing parenthesis
            }
        }
        else
        {
            return 0;  // invalid character
        }
    }

    // Check parenthesis balance and operator/operand relationship
    if (parenBalance != 0)
    {
        return 0;  // unmatched parentheses
    }

    // For a valid expression: operands = operators + 1
    if (operandCount != operatorCount + 1)
    {
        return 0;
    }

    return 1;
}

```

